import logging
from .creality_config import KINEMATIC_TYPE

class SafeZHoming:

    def __init__(self, config):
        self.printer = config.get_printer()
        x_pos, y_pos = config.getfloatlist("home_xy_position", count=2)
        self.home_x_pos, self.home_y_pos = x_pos, y_pos
        self.x_hop = config.getfloat("x_hop", default=0.0)
        self.y_hop = config.getfloat("y_hop", default=0.0)
        self.z_hop = config.getfloat("z_hop", default=0.0)
        self.hop_speed = config.getfloat("hop_speed", 15.0, above=0.0)
        self.x_wait = config.getfloat("x_wait", default=0.0)
        self.y_wait = config.getfloat("y_wait", default=0.0)
        self.tri_hold_mag = config.getfloat("tri_hold_mag", default=2.5)
        zconfig = config.getsection("stepper_z")
        self.max_z = zconfig.getfloat("position_max", note_valid=False)
        fs = self.printer.get_features()
        if fs.feature(KINEMATIC_TYPE) == "corexz":
            self.z_endstop_pos = zconfig.getfloat("position_endstop")
        self.speed = config.getfloat("speed", 50.0, above=0.0)
        self.move_to_previous = config.getboolean("move_to_previous", False)
        self.second_home = config.getboolean("second_home", False)
        self.printer.load_object(config, "homing")
        self.gcode = self.printer.lookup_object("gcode")
        self.prtouch = self.printer.lookup_object("prtouch_v3", None)
        self.prev_G28 = self.gcode.register_command("G28", None)
        self.gcode.register_command("G28", self.cmd_G28)
        if config.has_section("homing_override") or config.has_section("safe_z_home"):
            raise config.error("homing_override and safe_z_homing and creality_z_home cannot be used simultaneously")
        self.printer.register_event_handler("klippy:ready", self._handle_ready)

    def _handle_ready(self):
        self.harmonic = self.printer.lookup_object("harmonic_anc", default=None)

    def cmd_G28(self, gcmd):
        g28_map = {'corexy':self.cmd_G28_corexy, 
         'corexz':self.cmd_G28_corexz}
        fs = self.printer.get_features()
        for kin in g28_map.keys():
            if fs.feature(KINEMATIC_TYPE) == kin:
                g28_map[kin](gcmd)
                break

    def run_prev_G28(self, axis):
        toolhead = self.printer.lookup_object("toolhead")
        axis_seq = ord(axis) - ord("X")
        hops = (self.x_hop, self.y_hop)
        waits = (self.x_wait, self.y_wait)
        hop = hops[axis_seq]
        wait = waits[axis_seq]
        positive_dir = toolhead.get_kinematics().rails[axis_seq].homing_positive_dir
        _, position_max = toolhead.get_kinematics().rails[axis_seq].get_range()
        if hop != 0.0:
            curtime = self.printer.get_reactor().monotonic()
            kin_status = toolhead.get_kinematics().get_status(curtime)
            pos = toolhead.get_position()
            if axis.lower() in kin_status["homed_axes"]:
                move_pos = [None, None, None]
                if positive_dir is False:
                    if pos[axis_seq] < hop:
                        move_pos[axis_seq] = hop
                        toolhead.manual_move(move_pos, self.hop_speed)
                        toolhead.dwell(wait)
                    if positive_dir is True:
                        if pos[axis_seq] > position_max - hop:
                            move_pos[axis_seq] = position_max - hop
                            toolhead.manual_move(move_pos, self.hop_speed)
                            toolhead.dwell(wait)
        new_params = {}
        new_params[axis] = "0"
        g28_gcmd = self.gcode.create_gcode_command("G28", "G28", new_params)
        self.prev_G28(g28_gcmd)
        pos = toolhead.get_position()
        move_pos = [None, None, None]
        move_pos[axis_seq] = position_max - hop if positive_dir is True else hop
        toolhead.manual_move(move_pos, self.hop_speed)
        toolhead.dwell(wait)

    def cmd_G28_corexz(self, gcmd):
        """
        corexz, cartesian y, machinery: i3
        """
        toolhead = self.printer.lookup_object("toolhead")
        extra_es = self.printer.lookup_object("creality_extra_endstop")
        extra_es.close()
        self.gcode.run_script_from_command("RESET_GCODE_OFFSET")
        self.gcode.run_script_from_command("M220 S100")
        self.gcode.run_script_from_command("M221 S100")
        force_verify = False
        align_Z = gcmd.get("V", None) is not None
        if align_Z:
            params = gcmd.get_command_parameters()
            align = float(params["V"])
            gcmd.respond_info("Input verified: %.5f" % align)
            extra_es.set_verified_offset(align)
        keep_Z = gcmd.get("K", None) is not None
        need_x, need_y, need_z = [gcmd.get(axis, None) is not None for axis in "XYZ"]
        need_all = False
        if not need_x or need_y or need_z:
            need_all = need_x = need_y = need_z = True
        elif need_z:
            force_verify = True
        if need_x and need_y:
            if need_z:
                force_verify = True
                need_all = True
                self.gcode.run_script_from_command("BED_MESH_CLEAR")
            if not need_all or need_y:
                if not need_x or keep_Z:
                    curtime = self.printer.get_reactor().monotonic()
                    kin_status = toolhead.get_kinematics().get_status(curtime)
                    pos = toolhead.get_position()
                    if "z" not in kin_status["homed_axes"]:
                        pos[2] = 0
                        toolhead.set_position(pos, homing_axes=[2])
                        toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
                        if hasattr(toolhead.get_kinematics(), "note_z_not_homed"):
                            toolhead.get_kinematics().note_z_not_homed()
                        self.gcode.run_script_from_command("BED_MESH_CLEAR")
                    elif pos[2] < self.z_hop:
                        toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
                if need_x:
                    if extra_es.has_es("z"):
                        need_z = True
                        extra_es.flush_zpe()
                    else:
                        need_all = need_x = False
                        logging.warning("Warning: Ender3 need set extra_z_endstop_pin!")
            if need_z:
                extra_es.open()
                g28_gcmd = self.gcode.create_gcode_command("G28", "G28", {"Z": "0"})
                self.prev_G28(g28_gcmd)
            extra_es.close()
            if need_x:
                self.run_prev_G28("X")
            if need_y:
                self.run_prev_G28("Y")
            if need_z:
                if force_verify:
                    toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
                if need_all:
                    toolhead.manual_move([self.home_x_pos, self.home_y_pos], self.speed)
                if need_z:
                    if force_verify:
                        self.prtouch.mcu_probe.verify_coordinate()
                        toolhead.manual_move([None, None, extra_es.get_position_endstop("ze") - 30.0], 100.0)
                        extra_es.open()
                        g28_gcmd = self.gcode.create_gcode_command("G28", "G28", {"Z": "0"})
                        self.prev_G28(g28_gcmd)
                        extra_es.close()
                        toolhead.manual_move([None, None, 10.0], 100.0)
                        gcmd.respond_info("Done. (Verified: %.5f)" % extra_es.get_verified_offset())
                        self.prtouch.mcu_probe.try_to_load_mesh()
            pos = toolhead.get_position()
            gcmd.respond_info("Current position is {}".format(pos))

    def cmd_G28_corexy(self, gcmd):
        toolhead = self.printer.lookup_object("toolhead")
        self.gcode.run_script_from_command("RESET_GCODE_OFFSET")
        self.gcode.run_script_from_command("M220 S100")
        self.gcode.run_script_from_command("M221 S100")
        Keep_Z = gcmd.get("K", None) is not None
        if self.z_hop != 0.0 and not Keep_Z:
            curtime = self.printer.get_reactor().monotonic()
            kin_status = toolhead.get_kinematics().get_status(curtime)
            pos = toolhead.get_position()
            if "z" not in kin_status["homed_axes"]:
                pos[2] = 0
                toolhead.set_position(pos, homing_axes=[2])
                toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
                if hasattr(toolhead.get_kinematics(), "note_z_not_homed"):
                    toolhead.get_kinematics().note_z_not_homed()
                self.gcode.run_script_from_command("BED_MESH_CLEAR")
        else:
            if pos[2] < self.z_hop:
                toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
            need_x, need_y, need_z = [gcmd.get(axis, None) is not None for axis in "XYZ"]
            if need_z:
                curtime = self.printer.get_reactor().monotonic()
                kin_status = toolhead.get_kinematics().get_status(curtime)
                if "x" not in kin_status["homed_axes"] or "y" not in kin_status["homed_axes"]:
                    need_x = need_y = True
                if not need_x or need_y:
                    if not need_z:
                        need_x = need_y = need_z = True
                if need_x:
                    self.run_prev_G28("X")
                if need_y:
                    self.run_prev_G28("Y")
                if self.second_home:
                    if need_x:
                        self.run_prev_G28("X")
                    if need_y:
                        self.run_prev_G28("Y")
                ck_g28xy = toolhead.kin.limits
                if ck_g28xy[0][0] < ck_g28xy[0][1] and ck_g28xy[1][0] < ck_g28xy[1][1]:
                    if need_x and need_y:
                        if self.harmonic is not None:
                            self.gcode.run_script_from_command("HARMONIC_ALIGN")
                        if need_z:
                            prevpos = toolhead.get_position()
                            toolhead.manual_move([self.home_x_pos, self.home_y_pos], self.speed)
                            g28_gcmd = self.gcode.create_gcode_command("G28", "G28", {"Z": "0"})
                            self.prev_G28(g28_gcmd)
                            if self.z_hop:
                                pos = toolhead.get_position()
                                if pos[2] < self.z_hop:
                                    toolhead.manual_move([None, None, self.z_hop], self.hop_speed)
                            if self.move_to_previous:
                                toolhead.manual_move(prevpos[:2], self.speed)


def load_config(config):
    return SafeZHoming(config)

